      "port": 10853,
      "listen": "127.0.0.1",
      "protocol": "dokodemo-door",
      "settings": {
        "port": 53,
        "address": "1.1.1.1",
        "network": "tcp,udp"
      }
    }
  ],
  "outbounds": [
    {
      "protocol": "shadowsocks",
      "tag": "proxy",
      "settings": {
        "servers": [
